-- Wächter Migration 206 (nur lesen). Erwartungen: werkzeuge/m206_md5.json. schema = Aufbau von ally_person_rollen (vorher leer); funktionen = Fingerabdruck der
-- elf geänderten und drei neuen Funktionen (vorher nur die elf); vorlagen = Rollen anwender/mitarbeiter samt Rechten (vorher leer);
-- rb = Zahl der Sicherungstabellen aus Rückbau 206 (0 oder 4).
SELECT coalesce((SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_person_rollen'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x), '-') AS schema, (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_recht_roh', 'ally_person_rechte_basis', 'ally_rollen_ui', 'ally_rolle_ui_aktion', 'ally_ui_rahmen', 'ally_person_anlegen_abschliessen', 'ally_person_rolle_anwenden', 'ally_person_rolle_abgleichen', 'ally_rolle_papierkorb', 'ally_testdaten_entfernen', 'ally_sicherung_kunde_inhalt', 'ally_person_rollen_liste', 'ally_person_rollen_setzen', 'ally_rollen_person_ui_aktion'])) AS funktionen, (SELECT md5(coalesce(string_agg(z, E'\n' ORDER BY z COLLATE "C"), '')) FROM (SELECT r.schluessel || '|' || r.name || '|' || r.art || '|' || coalesce(r.vorlage, '') || '|' || coalesce(r.standard::text, '') || '|' || coalesce((SELECT string_agg(rr.recht || ':' || coalesce(rr.reichweite, '-'), ',' ORDER BY rr.recht COLLATE "C") FROM public.ally_rollen_rechte rr WHERE rr.rolle = r.schluessel), '') AS z FROM public.ally_rollen r WHERE r.schluessel = ANY (ARRAY['anwender', 'mitarbeiter'])) x) AS vorlagen, (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relname::text COLLATE "C" = ANY (ARRAY['ally_person_rollen_rb206', 'ally_rollen_vorlagen_rb206', 'ally_personen_rolle_rb206', 'ally_speicherort_rechte_rb206'])) AS rb;
